package com.orderflow.delivery.security;import com.orderflow.delivery.config.DeliverySecurityProperties;import java.util.*;import org.springframework.context.annotation.*;import org.springframework.core.convert.converter.Converter;import org.springframework.security.authentication.AbstractAuthenticationToken;import org.springframework.security.core.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;
@Configuration public class DeliveryJwtConfiguration{@Bean JwtDecoder deliveryJwtDecoder(DeliverySecurityProperties p){NimbusJwtDecoder d=NimbusJwtDecoder.withJwkSetUri(p.jwkSetUri()).jwsAlgorithm(SignatureAlgorithm.RS256).build();d.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(p.issuer()),new RequiredJwtClaimsValidator()));return d;}@Bean Converter<Jwt,AbstractAuthenticationToken>deliveryJwtAuthenticationConverter(){JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(j->{Collection<String>r=j.getClaimAsStringList("roles");return r==null?List.of():r.stream().map(x->(GrantedAuthority)new SimpleGrantedAuthority("ROLE_"+x)).toList();});return c;}}
